import { defineStore } from 'pinia';
import { LocalStorage } from 'quasar';
import { dynamicObj } from '../../pages/assets';
import { masterDataPrefix } from 'src/constants';
import { isUndefinedOrNull } from 'src/utils/general';
import { removeSortOrderFromStorage } from 'src/utils/ms_utlis';
import { purchaseOrderApiService } from 'src/services';
import { useAmountFormatStore, useSettingStore } from 'src/store/main';

export const usePoAndInvoiceStore = defineStore('po_and_invoice_store', {
  state: () => ({
    paginationCount: 0,
    statusCounts: {
      all: 0,
      open: 0,
      invoiced: 0,
      received: 0,
      closed: 0,
    },
    loading: true,
    pending_approval_supplier: 0,
    display_data: [] as dynamicObj,
    po_detail: {
      purchase_order: {} as any,
      purchase_order_line: [] as any,
    },
    preview_path: '',
    po_number_path: '',
    quickFilterMap: new Map(),
    pagination_size_key: 'PAGINATION_SIZE',
    params: {
      keyword: '',
      after_date: '',
      before_date: '',
      min_amount: '',
      max_amount: '',
      sort_by: '',
      order: '',
      order_status: '',
    },
    order_by: {} as dynamicObj,
    pagination: {
      current_page: 1,
      total_pages: 0,
      page_size: 25,
    },
    table_columns: {
      purchase_order_number: {
        name: 'purchase_order_number',
        translation_key: 'po_number',
        actions: true,
        order: 0,
      },
      status: {
        name: 'status',
        translation_key: 'order_status',
        actions: true,
        order: 1,
      },
      order_date: {
        name: 'order_date',
        translation_key: 'order_date',
        actions: true,
        format: (val: string, row: any) =>
          val ? useSettingStore().dateFormatOnly(val) : '',
        order: 2,
      },
      requested_shipment_date: {
        name: 'requested_shipment_date',
        translation_key: 'requested_delivery_date',
        actions: true,
        format: (val: string, row: any) =>
          val ? useSettingStore().dateFormatOnly(val) : '',
        order: 3,
      },
      total_amount: {
        name: 'total_amount',
        translation_key: 'total_amount',
        actions: true,
        order: 4,
      },
      ship_to_party_name: {
        name: 'ship_to_party_name',
        translation_key: 'ship_to_party_name',
        actions: true,
        order: 5,
      },
      warehouse_id: {
        name: 'warehouse_id',
        translation_key: 'location_id',
        actions: true,
        order: 6,
      },

      // order_status:{
      //     name:'order_status',
      //     translation_key: 'order_status',
      //     actions: true,
      //     order: 1,
      // },
      supplier_name: {
        name: 'supplier_name',
        translation_key: 'vendor',
        actions: true,
        order: 7,
      },
      po_lines: {
        name: 'po_lines',
        translation_key: 'po_lines',
        actions: true,
        order: 8,
      },
      // promised_delivery_date:{
      //     name:'promised_delivery_date',
      //     translation_key: 'promised_delivery_date',
      //     actions: true,
      //     format: (val: string, row: any) => val ? datePattern(val) : '',
      //     order: 8,
      // },
      // payment_terms_code:{
      //     name:'payment_terms_code',
      //     translation_key: 'payment_terms_code',
      //     actions: true,
      //     order: 9,
      // },
      // disponent_name:{
      //     name:'disponent_name',
      //     translation_key: 'disponent_name',
      //     actions: true,
      //     order: 11,
      // },
      // extended_amount:{
      //     name:'extended_amount',
      //     translation_key: 'extended_amount',
      //     actions: true,
      //     order: 12,
      // },
    } as dynamicObj,
  }),
  actions: {
    resetPagination() {
      this.pagination = {
        current_page: 1,
        total_pages: 0,
        page_size: 20,
      };
    },
    resetFilter() {
      this.params = {
        keyword: '',
        after_date: '',
        before_date: '',
        min_amount: '',
        max_amount: '',
        sort_by: '',
        order: '',
        order_status: '',
      };
      this.pagination = {
        current_page: 1,
        total_pages: 0,
        page_size: 20,
      };
      removeSortOrderFromStorage('supplier');
      this.order_by = {} as dynamicObj;
    },
    async getPurchaseOrderData() {
      this.loading = true;
      try {
        const filterObj: any = {};
        for (const [key, value] of Object.entries(this.params)) {
          const data = value as any;
          if (typeof data === 'object') {
            if (data && Object.keys(data).length > 0) {
              filterObj[key] = data.value;
            }
          } else if (data !== '') {
            filterObj[key] = data;
          }
        }
        const offset =
          (this.pagination.current_page - 1) * this.pagination.page_size;
        const response = await purchaseOrderApiService.purchase_order_dashboard(
          {
            ...filterObj,
            limit: this.pagination.page_size,
            skip: offset,
          },
        );

        if (!response) {
          throw response;
        }
        this.display_data = response.data;

        this.display_data.forEach((data: dynamicObj) => {
          logInfo(data.status);
          if (isUndefinedOrNull(data.status)) {
            data.status = '';
          }
        });

        this.paginationCount = response.metadata.total_results;
        this.statusCounts.all = response.metadata.total_records;
        this.statusCounts.open = response.metadata.total_all_open;
        this.statusCounts.invoiced = response.metadata.total_invoiced_count;
        this.statusCounts.received = response.metadata.total_received_count;
        this.statusCounts.closed = response.metadata.total_closed_count;
        this.pagination.total_pages = Math.ceil(
          response.metadata.total_results / this.pagination.page_size,
        );
      } catch (error) {
        throw error;
      } finally {
        this.loading = false;
      }

      // total amount formatting (non-blocking)
      this.formatTotalAmounts();
    },
    async formatTotalAmounts() {
      try {
        const values = this.display_data.map((data: dynamicObj) => {
          if (data.total_amount) {
            return { key: data.total_amount, value: data.total_amount };
          } else {
            return { key: 0, value: 0 };
          }
        });
        const { user_settings } = useSettingStore();
        const results = await useAmountFormatStore().formatMultiValues(
          values,
          'en_US',
          user_settings.AMOUNTS_LOCALE,
        );
        this.display_data = this.display_data.map((data: dynamicObj) => {
          return {
            ...data,
            total_amount: this.searchValueByKey(data.total_amount, results),
          };
        });
      } catch (err) {
        logError(err);
      }
    },
    searchValueByKey(key: string, values: dynamicObj[]) {
      return useAmountFormatStore().searchValueByKey(key, values);
    },
    async getPurchaseOrderDetail(po_number: string | number) {
      try {
        const response = await purchaseOrderApiService.purchase_order_detail({
          po_id: po_number,
        });
        if (!response) {
          throw response;
        }
        this.po_number_path = response?.purchase_order?.purchase_order_number;

        // using formatting total amount for purchase_order
        const values: Array<{ key: number; value: number }> = [];
        const totalAmount = response.purchase_order.total_amount ?? 0;
        values.push({
          key: totalAmount,
          value: totalAmount,
        });

        const settings_store = useSettingStore();
        let dest_locale = settings_store.user_settings.AMOUNTS_LOCALE;
        if (!dest_locale) {
          dest_locale = await settings_store.getSetting('AMOUNTS_LOCALE');
        }
        const results = await useAmountFormatStore().formatMultiValues(
          values,
          'en_US',
          dest_locale,
        );
        // using formatting total amount for purchase_order_line
        const valuesOrderLine: {
          key: string | number;
          value: string | number;
        }[] = [];
        response.purchase_order_lines.forEach((data: dynamicObj) => {
          if (data.total_amount) {
            valuesOrderLine.push({
              key: data.total_amount,
              value: data.total_amount,
            });
          } else {
            valuesOrderLine.push({
              key: 0,
              value: 0,
            });
          }

          if (data.unit_price) {
            valuesOrderLine.push({
              key: data.unit_price,
              value: data.unit_price,
            });
          } else {
            valuesOrderLine.push({
              key: 0,
              value: 0,
            });
          }
        });

        // all data po dashboard
        this.po_detail = {
          purchase_order: {
            ...response.purchase_order,
            total_amount: this.searchValueByKey(totalAmount, results),
          },
          purchase_order_line: response.purchase_order_lines,
        };
      } catch (error) {
        throw error;
      }
    },
    async getColumnPreference(master_lookup_type: string) {
      const key = masterDataPrefix + master_lookup_type.toUpperCase();
      const settings_store = useSettingStore();
      const setting = await settings_store.getSetting(key) as dynamicObj;
      return String(!setting ? '[]' : setting);
    },

    async getPreviewPath(po_id: string) {
      try {
        const userDetail: any = LocalStorage.getItem('user_details');
        const parentId = userDetail?.organisations[0]?.parent_org_id
          ? userDetail?.organisations[0]?.parent_org_id
          : userDetail.organisations[0].org_id;
        const response = await purchaseOrderApiService.getPOPreviewPath(po_id, {
          parent_id: parentId,
        });
        if (response.success) {
          this.preview_path = response?.data?.preview_path as string;
        }
      } catch (err: any) {
        logError(err);
      }
    },
    async getSavedColumnPreference(key: string) {
      const settings_store = useSettingStore();
      const saved_columns = await settings_store.getSetting(key) as dynamicObj;
      return String(!saved_columns ? '' : saved_columns);
    },
  },
});
